    struct boss_arlokk_coa : public BossAI
    {
        boss_arlokk_coa(Creature* creature) : BossAI(creature, DATA_ARLOKK) { }

        void Reset() override
        {
            _Reset();
            _summonCountA = 0;
            _summonCountB = 0;
            _marking = false;
            me->RemoveAurasDueToSpell(SPELL_ASPECT_OF_BETHEKK);
            me->RemoveAurasDueToSpell(SPELL_RAZOR_CLAWS);
            me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 0, WEAPON_DAGGER);
            me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 1, WEAPON_DAGGER);
            me->SetWalk(false);
            me->SetHomePosition(PosMoveOnSpawn);
            me->GetMotionMaster()->MoveTargetedHome();
        }

        void JustDied(Unit* /*killer*/) override
        {
            _JustDied();
            Talk(SAY_DEATH);
            ClearMarks();
        }

        void JustEngagedWith(Unit* /*who*/) override
        {
            _JustEngagedWith();
            Talk(SAY_AGGRO);

            events.SetPhase(PHASE_ONE);
            ScheduleTroll(2s);
            events.ScheduleEvent(EVENT_SUMMON_PROWLERS, 6s, 0, PHASE_ALL);
            events.ScheduleEvent(EVENT_MARK_OF_ARLOKK, 10s, 0, PHASE_ALL);

            // The panther spawners, split by side as in stock.
            std::list<Creature*> triggers;
            GetCreatureListWithEntryInGrid(triggers, me, NPC_PANTHER_TRIGGER, 100.0f);
            uint8 sideA = 0, sideB = 0;
            for (Creature* trigger : triggers)
            {
                if (trigger->GetPositionY() < -1625.0f)
                {
                    if (sideA < 5)
                        _sideA[sideA++] = trigger->GetGUID();
                }
                else if (sideB < 5)
                    _sideB[sideB++] = trigger->GetGUID();
            }
        }

        void ScheduleTroll(Milliseconds swp)
        {
            events.ScheduleEvent(EVENT_SHADOW_WORD_PAIN, swp, 0, PHASE_ONE);
            events.ScheduleEvent(EVENT_KIDNEY_SHOT, 15s, 0, PHASE_ONE);
            events.ScheduleEvent(EVENT_TRANSFORM, 30s, 0, PHASE_ONE);
        }

        void JustReachedHome() override
        {
            if (GameObject* gong = ObjectAccessor::GetGameObject(*me, instance->GetGuidData(GO_GONG_OF_BETHEKK)))
                gong->RemoveGameObjectFlag(GO_FLAG_NOT_SELECTABLE);
            me->DespawnOrUnsummon();
        }

        void EnterEvadeMode(EvadeReason why) override
        {
            BossAI::EnterEvadeMode(why);
            ClearMarks();
            std::list<Creature*> panthers;
            GetCreatureListWithEntryInGrid(panthers, me, NPC_ZULIAN_PROWLER, 200.0f);
            for (Creature* panther : panthers)
                panther->DespawnOrUnsummon();
        }

        // A prowler died on side 1 or 2.
        void SetData(uint32 id, uint32 /*value*/) override
        {
            if (id == 1 && _summonCountA)
                --_summonCountA;
            else if (id == 2 && _summonCountB)
                --_summonCountB;
        }

        void OnSpellCast(SpellInfo const* spell) override
        {
            BossAI::OnSpellCast(spell);

            Unit* target = ObjectAccessor::GetUnit(*me, _target);
            if (spell->Id == SPELL_SHADOW_WORD_PAIN)
                Hit(me, target, SPELL_SHADOW_WORD_PAIN_DOT, Info(me, INFO_SHADOW_WORD_PAIN));
            else if (spell->Id == SPELL_MARK_OF_ARLOKK && target)
            {
                me->AddAura(SPELL_MARK_OF_ARLOKK_AURA, target);
                Talk(SAY_FEAST_PROWLER, target);
            }
        }

        Player* Marked()
        {
            for (Player* p : Players(me, [](Player* x) { return x->HasAura(SPELL_MARK_OF_ARLOKK_AURA); }))
                return p;
            return nullptr;
        }

        void ClearMarks()
        {
            me->GetMap()->DoForAllPlayers([](Player* p) { p->RemoveAurasDueToSpell(SPELL_MARK_OF_ARLOKK_AURA); });
        }

        void Mark()
        {
            if (Unit* target = SelectTarget(SelectTargetMethod::Random, 1, 100.0f, true))
            {
                _target = target->GetGUID();
                DoCast(target, SPELL_MARK_OF_ARLOKK, true);
            }
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim())
                return;

            events.Update(diff);

            if (me->HasUnitState(UNIT_STATE_CASTING))
                return;

            while (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_SHADOW_WORD_PAIN:
                        if (Unit* tank = me->GetVictim())
                        {
                            _target = tank->GetGUID();
                            DoCast(tank, SPELL_SHADOW_WORD_PAIN);
                        }
                        events.ScheduleEvent(EVENT_SHADOW_WORD_PAIN, 20s, 0, PHASE_ONE);
                        break;
                    case EVENT_KIDNEY_SHOT:
                        DoCastVictim(SPELL_KIDNEY_SHOT);
                        events.ScheduleEvent(EVENT_KIDNEY_SHOT, 30s, 0, PHASE_ONE);
                        break;
                    case EVENT_MARK_OF_ARLOKK:
                        _marking = true;
                        Mark();
                        events.ScheduleEvent(EVENT_MARK_CHECK, 2s, 0, PHASE_ALL);
                        break;
                    case EVENT_MARK_CHECK:
                        if (Player* marked = Marked())
                        {
                            std::list<Creature*> prowlers;
                            GetCreatureListWithEntryInGrid(prowlers, marked, NPC_ZULIAN_PROWLER, MARK_PULL_RANGE);
                            for (Creature* prowler : prowlers)
                                if (prowler->IsAlive() && prowler->GetVictim() != marked)
                                {
                                    prowler->GetThreatMgr().AddThreat(marked, 100000.0f);
                                    prowler->AI()->AttackStart(marked);
                                }
                        }
                        else if (_marking)
                            Mark();   // the mark jumps
                        events.ScheduleEvent(EVENT_MARK_CHECK, 2s, 0, PHASE_ALL);
                        break;
                    case EVENT_SUMMON_PROWLERS:
                        if (_summonCountA < MAX_PROWLERS_PER_SIDE)
                            if (Unit* trigger = ObjectAccessor::GetUnit(*me, _sideA[urand(0, 4)]))
                            {
                                trigger->CastSpell(trigger, SPELL_SUMMON_PROWLER);
                                ++_summonCountA;
                            }
                        if (_summonCountB < MAX_PROWLERS_PER_SIDE)
                            if (Unit* trigger = ObjectAccessor::GetUnit(*me, _sideB[urand(0, 4)]))
                            {
                                trigger->CastSpell(trigger, SPELL_SUMMON_PROWLER);
                                ++_summonCountB;
                            }
                        events.ScheduleEvent(EVENT_SUMMON_PROWLERS, 6s, 0, PHASE_ALL);
                        break;
                    case EVENT_TRANSFORM:
                        DoCastSelf(SPELL_ASPECT_OF_BETHEKK, true);
                        me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 0, EQUIP_UNEQUIP);
                        me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 1, EQUIP_UNEQUIP);
                        me->AttackStop();
                        DoResetThreatList();
                        me->SetReactState(REACT_PASSIVE);
                        me->SetUnitFlag(UNIT_FLAG_NON_ATTACKABLE | UNIT_FLAG_NOT_SELECTABLE);
                        DoCastSelf(SPELL_VANISH_VISUAL);
                        DoCastSelf(SPELL_VANISH);
                        events.ScheduleEvent(EVENT_VANISH, 1s, 0, PHASE_ONE);
                        break;
                    case EVENT_VANISH:
                        DoCastSelf(SPELL_SUPER_INVIS);
                        me->SetWalk(false);
                        me->GetMotionMaster()->MovePoint(0, frand(-11551.0f, -11508.0f), frand(-1638.0f, -1617.0f), me->GetPositionZ());
                        events.ScheduleEvent(EVENT_VANISH_2, 9s, 0, PHASE_ONE);
                        break;
                    case EVENT_VANISH_2:
                        DoCastSelf(SPELL_VANISH);
                        DoCastSelf(SPELL_SUPER_INVIS);
                        events.ScheduleEvent(EVENT_VISIBLE, 41s, 47s, 0, PHASE_ONE);
                        break;
                    case EVENT_VISIBLE:
                        me->SetReactState(REACT_AGGRESSIVE);
                        me->RemoveUnitFlag(UNIT_FLAG_NON_ATTACKABLE | UNIT_FLAG_NOT_SELECTABLE);
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0))
                            AttackStart(target);
                        me->RemoveAurasDueToSpell(SPELL_SUPER_INVIS);
                        me->RemoveAurasDueToSpell(SPELL_VANISH);
                        DoCastSelf(SPELL_RAZOR_CLAWS, true);
                        events.SetPhase(PHASE_TWO);
                        events.ScheduleEvent(EVENT_CLAW_STORM, 5s, 0, PHASE_TWO);
                        events.ScheduleEvent(EVENT_RAVAGE, 10s, 0, PHASE_TWO);
                        events.ScheduleEvent(EVENT_SHADOWSTEP, 12s, 0, PHASE_TWO);
                        events.ScheduleEvent(EVENT_TRANSFORM_BACK, 30s, 40s, 0, PHASE_TWO);
                        break;
                    case EVENT_CLAW_STORM:
                        DoCastSelf(SPELL_CLAW_STORM);
                        events.ScheduleEvent(EVENT_CLAW_STORM, 20s, 0, PHASE_TWO);
                        break;
                    case EVENT_RAVAGE:
                        DoCastVictim(SPELL_RAVAGE, true);
                        events.ScheduleEvent(EVENT_RAVAGE, 15s, 0, PHASE_TWO);
                        break;
                    case EVENT_SHADOWSTEP:
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, 40.0f, true))
                        {
                            DoCast(target, SPELL_SHADOWSTEP);
                            AttackStart(target);
                        }
                        events.ScheduleEvent(EVENT_SHADOWSTEP, 15s, 0, PHASE_TWO);
                        break;
                    case EVENT_TRANSFORM_BACK:
                        me->RemoveAurasDueToSpell(SPELL_ASPECT_OF_BETHEKK);
                        me->RemoveAurasDueToSpell(SPELL_RAZOR_CLAWS);
                        DoCastSelf(SPELL_VANISH_VISUAL);
                        me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 0, WEAPON_DAGGER);
                        me->SetUInt32Value(UNIT_VIRTUAL_ITEM_SLOT_ID + 1, WEAPON_DAGGER);
                        events.SetPhase(PHASE_ONE);
                        ScheduleTroll(4s);
                        break;
                    default:
                        break;
                }

                if (me->HasUnitState(UNIT_STATE_CASTING))
                    break;
            }

            DoMeleeAttackIfReady();
        }

    private:
        uint8 _summonCountA = 0;
        uint8 _summonCountB = 0;
        bool _marking = false;
        ObjectGuid _sideA[5];
        ObjectGuid _sideB[5];
        ObjectGuid _target;
    };
}

void AddCoaArlokkScripts()
{
    RegisterZulGurubCreatureAI(boss_arlokk_coa);
}

/*
 * High Priestess Mar'li with Ascension's spells.
 *
 * Kit: Ascension's block 2118100-2118151. Timings: a Bronzebeard kill on video,
 * see raid-difficulty-werkzeug/zg-video-zeitplan.json. Stock swaps between
 * troll and spider every minute; on Ascension she stays a troll until 50% and
 * a spider after (in the video from 49%, 230s in).
 *
 *   Troll form
 *     Drain Life         first 6s,  every 10s   random player, interruptible
 *     Poison Bolt Volley first 12s, every 15s   everyone, stacking poison
 *     Hatch Eggs         at 17s                  the four nearest eggs hatch
 *     Evolve             first 22s, every 60s   an egg hatches a colossal spider
 *     Infest             first 87s, every 60s   an egg hatches a festering
 *                                               spider that bursts on death
 *
 *   Spider form, at 50%
 *     Acid Spit          first 1s,  every 12s   on the tank, poison and -10% armour
 *     Web Spray          first 15s, every 55s   everyone within 20 yards is
 *                                               slowed, then webbed; then she
 *                                               charges a caster, as in stock
 *     Poison Shock       first 25s, every 25s   20 yards around her
 *     Furious Strikes    passive, her hits speed her up
 *
 * Decided here, not in the data:
 *   - Evolve and Infest act on an egg she hatches for it: the spawn of Evolve
 *     is twice the size with twice the health; the spawn of Infest bursts for
 *     Poison Shock's damage where it dies;
 *   - Drain Life heals her for what each tick deals;
 *   - Poison Shock's timer (the video never shows it); no falloff with range.
 */

#include "CreatureScript.h"
#include "GameObject.h"
#include "ScriptedCreature.h"
#include "../../../src/server/scripts/EasternKingdoms/ZulGurub/zulgurub.h"
#include "zg_coa_common.h"

#include <list>

using namespace coa_zg;

namespace
{
    enum Says
    {
        SAY_AGGRO        = 0,
        SAY_TRANSFORM    = 1,
        SAY_SPIDER_SPAWN = 2,
        SAY_DEATH        = 3
    };

    enum Spells
    {
        SPELL_THRASH              = 3391,
        SPELL_CHARGE              = 22911,

        INFO_DRAIN_LIFE           = 2118101,
        SPELL_DRAIN_LIFE          = 2118105,
        SPELL_DRAIN_LIFE_TICK     = 2118107,
        SPELL_DRAIN_LIFE_HEAL     = 2118108,
        SPELL_POISON_BOLT_VOLLEY  = 2118109,
        SPELL_POISON_BOLT_HIT     = 2118110,
        SPELL_HATCH_EGGS          = 2118115,
        SPELL_EVOLVE              = 2118116,
        SPELL_ASPECT_OF_SHADRA    = 2118123,
        SPELL_FURIOUS_STRIKES     = 2118125,
        SPELL_ACID_SPIT           = 2118127,
        SPELL_ACID_SPIT_DOT       = 2118128,
        SPELL_CORROSION           = 2118132,
        SPELL_WEB_SPRAY           = 2118133,
        SPELL_POISON_SHOCK        = 2118145,
        SPELL_POISON_SHOCK_HIT    = 2118146,
        SPELL_INFEST              = 2118151,
    };

    enum Misc
    {
        GO_SPIDER_EGGS     = 179985,
        NPC_SPAWN_OF_MARLI = 15041,
        NPC_WORLD_TRIGGER  = 12999
    };

    enum Events
    {
        EVENT_THRASH = 1,
        EVENT_DRAIN_LIFE,
        EVENT_POISON_BOLT_VOLLEY,
        EVENT_HATCH_EGGS,
        EVENT_EVOLVE,
        EVENT_INFEST,
        EVENT_ACID_SPIT,
        EVENT_WEB_SPRAY,
        EVENT_CHARGE,
        EVENT_POISON_SHOCK,
    };

    enum Phases
    {
        PHASE_TROLL  = 1,
        PHASE_SPIDER = 2
    };

    constexpr float VOLLEY_RANGE = 200.0f;
    constexpr uint8 FIRST_HATCH  = 4;

    struct boss_marli_coa : public BossAI
    {
        boss_marli_coa(Creature* creature) : BossAI(creature, DATA_MARLI) { }

        void Reset() override
        {
            me->RemoveAurasDueToSpell(SPELL_ASPECT_OF_SHADRA);
            me->RemoveAurasDueToSpell(SPELL_FURIOUS_STRIKES);
            _spider = false;
            _festering.clear();

            std::list<GameObject*> eggs;
            me->GetGameObjectListWithEntryInGrid(eggs, GO_SPIDER_EGGS, DEFAULT_VISIBILITY_INSTANCE);
            for (GameObject* egg : eggs)
            {
                egg->Respawn();
                egg->UpdateObjectVisibility();
            }
            BossAI::Reset();
        }

        void JustEngagedWith(Unit* who) override
        {
            BossAI::JustEngagedWith(who);
            Talk(SAY_AGGRO);

            events.SetPhase(PHASE_TROLL);
            events.ScheduleEvent(EVENT_THRASH, 4s, 6s);
            events.ScheduleEvent(EVENT_DRAIN_LIFE, 6s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_POISON_BOLT_VOLLEY, 12s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_HATCH_EGGS, 17s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_EVOLVE, 22s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_INFEST, 87s, 0, PHASE_TROLL);
        }

        void JustDied(Unit* killer) override
        {
            BossAI::JustDied(killer);
            Talk(SAY_DEATH);
        }

        void DamageTaken(Unit* attacker, uint32& damage, DamageEffectType type, SpellSchoolMask school) override
        {
            BossAI::DamageTaken(attacker, damage, type, school);

            if (_spider || !me->HealthBelowPctDamaged(50, damage))
                return;

            _spider = true;
            me->InterruptNonMeleeSpells(false);
            Talk(SAY_TRANSFORM);
            DoCastSelf(SPELL_ASPECT_OF_SHADRA, true);
            DoCastSelf(SPELL_FURIOUS_STRIKES, true);

            events.SetPhase(PHASE_SPIDER);
            events.ScheduleEvent(EVENT_ACID_SPIT, 1s, 0, PHASE_SPIDER);
            events.ScheduleEvent(EVENT_WEB_SPRAY, 15s, 0, PHASE_SPIDER);
            events.ScheduleEvent(EVENT_POISON_SHOCK, 25s, 0, PHASE_SPIDER);
        }

        void OnSpellCast(SpellInfo const* spell) override
        {
            BossAI::OnSpellCast(spell);

            switch (spell->Id)
            {
                case SPELL_POISON_BOLT_VOLLEY:
                    for (Player* p : PlayersWithin(me, VOLLEY_RANGE))
                        me->CastSpell(p, SPELL_POISON_BOLT_HIT, true);
                    break;
                case SPELL_HATCH_EGGS:
                    Talk(SAY_SPIDER_SPAWN);
                    for (uint8 i = 0; i < FIRST_HATCH; ++i)
                        HatchEgg();
                    break;
                case SPELL_ACID_SPIT:
                    if (Unit* tank = me->GetVictim())
                    {
                        me->CastSpell(tank, SPELL_ACID_SPIT_DOT, true);
                        me->CastSpell(tank, SPELL_CORROSION, true);
                    }
                    break;
                case SPELL_POISON_SHOCK:
                    me->CastSpell(me, SPELL_POISON_SHOCK_HIT, true);
                    break;
                default:
                    break;
            }
        }

        void SpellHitTarget(Unit* target, SpellInfo const* spell) override
        {
            switch (spell->Id)
            {
                case SPELL_EVOLVE:
                    target->SetMaxHealth(target->GetMaxHealth() * 2);
                    target->SetFullHealth();
                    break;
                case SPELL_INFEST:
                    _festering.insert(target->GetGUID());
                    break;
                // Drain Life heals her for what each tick deals.
                case SPELL_DRAIN_LIFE_TICK:
                {
                    int32 heal = Info(me, INFO_DRAIN_LIFE);
                    me->CastCustomSpell(me, SPELL_DRAIN_LIFE_HEAL, &heal, nullptr, nullptr, true);
                    break;
                }
                default:
                    break;
            }
        }

        // A festering spawn bursts where it dies.
        void SummonedCreatureDies(Creature* summon, Unit* killer) override
        {
            BossAI::SummonedCreatureDies(summon, killer);
            if (!_festering.erase(summon->GetGUID()))
                return;
            if (Creature* spot = me->SummonCreature(NPC_WORLD_TRIGGER, summon->GetPosition(), TEMPSUMMON_TIMED_DESPAWN, 5000))
            {
                spot->SetFaction(me->GetFaction());
                spot->CastSpell(spot, SPELL_POISON_SHOCK_HIT, true, nullptr, nullptr, me->GetGUID());
            }
        }

        // The nearest egg still standing hatches a Spawn of Mar'li.
        Creature* HatchEgg()
        {
            std::list<GameObject*> eggs;
            me->GetGameObjectListWithEntryInGrid(eggs, GO_SPIDER_EGGS, 100.0f);
            GameObject* nearest = nullptr;
            for (GameObject* egg : eggs)
                if (egg->isSpawned() && (!nearest || me->GetDistance(egg) < me->GetDistance(nearest)))
                    nearest = egg;
            if (!nearest)
                return nullptr;

            Creature* spawn = me->SummonCreature(NPC_SPAWN_OF_MARLI, nearest->GetPosition(), TEMPSUMMON_CORPSE_TIMED_DESPAWN, 60000);
            nearest->SetLootState(GO_JUST_DEACTIVATED);
            if (spawn)
                spawn->SetInCombatWithZone();
            return spawn;
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim())
                return;

            events.Update(diff);

            if (me->HasUnitState(UNIT_STATE_CASTING))
                return;

            while (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_THRASH:
                        DoCastVictim(SPELL_THRASH);
                        events.ScheduleEvent(EVENT_THRASH, 10s, 20s);
                        break;
                    case EVENT_DRAIN_LIFE:
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, 100.0f, true))
                        {
                            int32 tick = Info(me, INFO_DRAIN_LIFE);
                            me->CastCustomSpell(target, SPELL_DRAIN_LIFE, nullptr, &tick, nullptr, false);
                        }
                        events.ScheduleEvent(EVENT_DRAIN_LIFE, 10s, 0, PHASE_TROLL);
                        break;
                    case EVENT_POISON_BOLT_VOLLEY:
                        DoCastSelf(SPELL_POISON_BOLT_VOLLEY);
                        events.ScheduleEvent(EVENT_POISON_BOLT_VOLLEY, 15s, 0, PHASE_TROLL);
                        break;
                    case EVENT_HATCH_EGGS:
                        DoCastSelf(SPELL_HATCH_EGGS);
                        break;
                    case EVENT_EVOLVE:
                        if (Creature* spawn = HatchEgg())
                            DoCast(spawn, SPELL_EVOLVE);
                        events.ScheduleEvent(EVENT_EVOLVE, 60s, 0, PHASE_TROLL);
                        break;
                    case EVENT_INFEST:
                        if (Creature* spawn = HatchEgg())
                            DoCast(spawn, SPELL_INFEST);
                        events.ScheduleEvent(EVENT_INFEST, 60s, 0, PHASE_TROLL);
                        break;
                    case EVENT_ACID_SPIT:
                        DoCastVictim(SPELL_ACID_SPIT);
                        events.ScheduleEvent(EVENT_ACID_SPIT, 12s, 0, PHASE_SPIDER);
                        break;
                    case EVENT_WEB_SPRAY:
                        DoCastSelf(SPELL_WEB_SPRAY);
                        events.ScheduleEvent(EVENT_CHARGE, 5s, 0, PHASE_SPIDER);
                        events.ScheduleEvent(EVENT_WEB_SPRAY, 55s, 0, PHASE_SPIDER);
                        break;
                    case EVENT_CHARGE:
                        // From stock: after the webs she goes for a caster out of reach.
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, [this](Unit* u)
                            {
                                return u->IsPlayer() && u->getPowerType() == POWER_MANA && !me->IsWithinMeleeRange(u) && u != me->GetVictim();
                            }))
                        {
                            DoCast(target, SPELL_CHARGE);
                            AttackStart(target);
                        }
                        break;
                    case EVENT_POISON_SHOCK:
                        DoCastSelf(SPELL_POISON_SHOCK);
                        events.ScheduleEvent(EVENT_POISON_SHOCK, 25s, 0, PHASE_SPIDER);
                        break;
                }

                if (me->HasUnitState(UNIT_STATE_CASTING))
                    break;
            }

            DoMeleeAttackIfReady();
        }

    private:
        bool _spider = false;
        GuidSet _festering;
    };
}

void AddCoaMarliScripts()
{
    RegisterZulGurubCreatureAI(boss_marli_coa);
}

/*
 * High Priestess Jeklik with Ascension's spells.
 *
 * Kit: Ascension's block 2106100-2106143. Timings: a Bronzebeard kill on video,
 * see raid-difficulty-werkzeug/zg-video-zeitplan.json. On Ascension the phases
 * run the other way round from stock: she fights as a troll first and takes
 * bat form at 50% (in the video at 50%, 147s into the fight).
 *
 *   Troll form, from landing
 *     Mind Flay         first 4s,  every 14s   on the tank, interruptible
 *     Mass Fear         first 12s, every 48s   everyone within 20 yards
 *     Shadow Word: Pain first 15s, every 27s   random player
 *     Curse of Blood    first 16s, every 31s   random player and those near
 *     Call of Hir'eek   first 20s              six Bloodseeker Bats
 *     Greater Heal      first 29s, every 46s   20% of her health, interruptible
 *
 *   Bat form, at 50%
 *     Bat-tering Charge  first 2s, every 20s   random player, knocks back
 *                                              everyone within 10 yards
 *     Terrifying Screech first 4s, every 20s   everyone in the room
 *     Vampirism          passive, her hits drain life
 *     Bat Riders         two, from stock, throwing liquid fire
 *
 * Decided here, not in the data:
 *   - Call of Hir'eek every 60s (the video shows it once);
 *   - Terrifying Screech falls off with distance, full at her, nothing at 100
 *     yards (the tooltip says "reduced as farther", not by how much);
 *   - the bat riders move from the troll phase to the bat phase with the swap.
 */

#include "CreatureScript.h"
#include "MoveSplineInit.h"
#include "ScriptedCreature.h"
#include "../../../src/server/scripts/EasternKingdoms/ZulGurub/zulgurub.h"
#include "zg_coa_common.h"

using namespace coa_zg;

namespace
{
    enum Says
    {
        SAY_AGGRO         = 0,
        SAY_CALL_RIDERS   = 1,
        SAY_DEATH         = 2,
        EMOTE_SUMMON_BATS = 3,
        EMOTE_GREAT_HEAL  = 4
    };

    enum Spells
    {
        SPELL_GREEN_CHANNELING    = 13540,
        SPELL_BAT_FORM            = 23966,

        INFO_MIND_FLAY            = 2106101,
        SPELL_MIND_FLAY           = 2106105,
        INFO_SHADOW_WORD_PAIN     = 2106108,
        SPELL_SHADOW_WORD_PAIN    = 2106112,
        SPELL_SHADOW_WORD_PAIN_DOT = 2106113,
        SPELL_MASS_FEAR           = 2106114,
        SPELL_MASS_FEAR_HIT       = 2106115,
        SPELL_GREATER_HEAL        = 2106116,
        SPELL_CURSE_OF_BLOOD      = 2106117,
        SPELL_CURSE_OF_BLOOD_HIT  = 2106118,
        SPELL_CALL_OF_HIREEK      = 2106120,
        SPELL_ASPECT_OF_HIREEK    = 2106122,
        SPELL_BATTERING_CHARGE    = 2106125,
        SPELL_BATTERING_STUN      = 2106126,
        SPELL_BATTERING_IMPACT    = 2106127,
        SPELL_SCREECH             = 2106131,
        INFO_SCREECH              = 2106132,
        SPELL_SCREECH_HIT         = 2106136,
        SPELL_VAMPIRISM           = 2106138,
    };

    enum Npcs
    {
        NPC_BLOODSEEKER_BAT = 11368,
        NPC_BATRIDER        = 14750
    };

    enum Events
    {
        EVENT_MIND_FLAY = 1,
        EVENT_MASS_FEAR,
        EVENT_SHADOW_WORD_PAIN,
        EVENT_CURSE_OF_BLOOD,
        EVENT_CALL_OF_HIREEK,
        EVENT_GREATER_HEAL,
        EVENT_BATTERING_CHARGE,
        EVENT_SCREECH,
        EVENT_BAT_RIDER,
    };

    enum Phases
    {
        PHASE_TROLL = 1,
        PHASE_BAT   = 2
    };

    constexpr uint32 PATH_JEKLIK_INTRO = 145170;
    constexpr float MASS_FEAR_RANGE    = 20.0f;
    constexpr float SCREECH_RANGE      = 100.0f;

    Position const SpawnBat[6] =
    {
        { -12291.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12289.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12293.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12291.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12289.6220f, -1380.2640f, 144.8304f, 5.483f },
        { -12293.6220f, -1380.2640f, 144.8304f, 5.483f }
    };
    Position const SpawnBatRider = { -12301.689f, -1371.2921f, 145.09244f, 0.0f };
    Position const JeklikCaveHomePosition = { -12291.9f, -1380.08f, 144.902f, 2.28638f };

    struct boss_jeklik_coa : public BossAI
    {
        boss_jeklik_coa(Creature* creature) : BossAI(creature, DATA_JEKLIK) { }

        void Reset() override
        {
            BossAI::Reset();
            me->SetHomePosition(JeklikCaveHomePosition);
            me->SetDisableGravity(false);
            me->SetReactState(REACT_PASSIVE);
            me->SetCombatMovement(false);
            me->RemoveAurasDueToSpell(SPELL_ASPECT_OF_HIREEK);
            me->RemoveAurasDueToSpell(SPELL_VAMPIRISM);
            _bat = false;
            _riders = 0;
            DoCastSelf(SPELL_GREEN_CHANNELING, true);
        }

        // From stock: she flies down from her cave in bat form.
        void JustEngagedWith(Unit* who) override
        {
            BossAI::JustEngagedWith(who);
            Talk(SAY_AGGRO);
            DoZoneInCombat();
            me->RemoveAurasDueToSpell(SPELL_GREEN_CHANNELING);
            me->SetDisableGravity(true);
            DoCastSelf(SPELL_BAT_FORM, true);
            me->GetMotionMaster()->MoveWaypoint(PATH_JEKLIK_INTRO, false);
        }

        void PathEndReached(uint32 pathId) override
        {
            BossAI::PathEndReached(pathId);
            me->RemoveAurasDueToSpell(SPELL_BAT_FORM);
            me->SetDisableGravity(false);
            me->SetCombatMovement(true);
            me->SetReactState(REACT_AGGRESSIVE);

            events.SetPhase(PHASE_TROLL);
            events.ScheduleEvent(EVENT_MIND_FLAY, 4s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_MASS_FEAR, 12s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_SHADOW_WORD_PAIN, 15s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_CURSE_OF_BLOOD, 16s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_CALL_OF_HIREEK, 20s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_GREATER_HEAL, 29s, 0, PHASE_TROLL);
        }

        void EnterEvadeMode(EvadeReason why) override
        {
            if (why != EvadeReason::EVADE_REASON_NO_PATH)
                me->DespawnOnEvade(5s);
            BossAI::EnterEvadeMode(why);
        }

        void JustDied(Unit* killer) override
        {
            BossAI::JustDied(killer);
            Talk(SAY_DEATH);
        }

        void DamageTaken(Unit* attacker, uint32& damage, DamageEffectType type, SpellSchoolMask school) override
        {
            BossAI::DamageTaken(attacker, damage, type, school);

            if (_bat || !me->HealthBelowPctDamaged(50, damage))
                return;

            _bat = true;
            me->InterruptNonMeleeSpells(false);
            DoCastSelf(SPELL_ASPECT_OF_HIREEK, true);
            DoCastSelf(SPELL_VAMPIRISM, true);
            DoResetThreatList();

            events.SetPhase(PHASE_BAT);
            events.ScheduleEvent(EVENT_BATTERING_CHARGE, 2s, 0, PHASE_BAT);
            events.ScheduleEvent(EVENT_SCREECH, 4s, 0, PHASE_BAT);
            events.ScheduleEvent(EVENT_BAT_RIDER, 10s, 0, PHASE_BAT);
        }

        void OnSpellCast(SpellInfo const* spell) override
        {
            BossAI::OnSpellCast(spell);

            Unit* target = ObjectAccessor::GetUnit(*me, _target);
            switch (spell->Id)
            {
                case SPELL_MASS_FEAR:
                    for (Player* p : PlayersWithin(me, MASS_FEAR_RANGE))
                        me->CastSpell(p, SPELL_MASS_FEAR_HIT, true);
                    break;
                case SPELL_SHADOW_WORD_PAIN:
                    Hit(me, target, SPELL_SHADOW_WORD_PAIN_DOT, Info(me, INFO_SHADOW_WORD_PAIN));
                    break;
                case SPELL_CURSE_OF_BLOOD:
                    if (target)
                        me->CastSpell(target, SPELL_CURSE_OF_BLOOD_HIT, true);
                    break;
                case SPELL_CALL_OF_HIREEK:
                    CallOfHireek();
                    break;
                case SPELL_SCREECH:
                {
                    int32 const full = Info(me, INFO_SCREECH);
                    for (Player* p : PlayersWithin(me, SCREECH_RANGE))
                        Hit(me, p, SPELL_SCREECH_HIT, int32(full * (1.0f - me->GetDistance(p) / SCREECH_RANGE)), 1);
                    break;
                }
                default:
                    break;
            }
        }

        // The charge stuns its target; the impact around it is its own spell.
        void SpellHitTarget(Unit* target, SpellInfo const* spell) override
        {
            if (spell->Id == SPELL_BATTERING_STUN)
                me->CastSpell(target, SPELL_BATTERING_IMPACT, true);
        }

        void CallOfHireek()
        {
            Talk(EMOTE_SUMMON_BATS);
            Unit* target = SelectTarget(SelectTargetMethod::Random, 0, 100.0f, true);
            for (Position const& pos : SpawnBat)
                if (Creature* bat = me->SummonCreature(NPC_BLOODSEEKER_BAT, pos, TEMPSUMMON_TIMED_DESPAWN_OUT_OF_COMBAT, 15000))
                    if (target)
                        bat->AI()->AttackStart(target);
        }

        bool CastOnRandom(uint32 spell, bool notTank = false)
        {
            if (Unit* target = SelectTarget(SelectTargetMethod::Random, notTank ? 1 : 0, 100.0f, true))
            {
                _target = target->GetGUID();
                DoCast(target, spell);
                return true;
            }
            return false;
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim())
                return;

            events.Update(diff);

            if (me->HasUnitState(UNIT_STATE_CASTING))
                return;

            while (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_MIND_FLAY:
                        if (Unit* tank = me->GetVictim())
                        {
                            int32 tick = Info(me, INFO_MIND_FLAY);
                            me->CastCustomSpell(tank, SPELL_MIND_FLAY, nullptr, &tick, nullptr, false);
                        }
                        events.ScheduleEvent(EVENT_MIND_FLAY, 14s, 0, PHASE_TROLL);
                        break;
                    case EVENT_MASS_FEAR:
                        DoCastSelf(SPELL_MASS_FEAR);
                        events.ScheduleEvent(EVENT_MASS_FEAR, 48s, 0, PHASE_TROLL);
                        break;
                    case EVENT_SHADOW_WORD_PAIN:
                        CastOnRandom(SPELL_SHADOW_WORD_PAIN);
                        events.ScheduleEvent(EVENT_SHADOW_WORD_PAIN, 27s, 0, PHASE_TROLL);
                        break;
                    case EVENT_CURSE_OF_BLOOD:
                        CastOnRandom(SPELL_CURSE_OF_BLOOD);
                        events.ScheduleEvent(EVENT_CURSE_OF_BLOOD, 31s, 0, PHASE_TROLL);
                        break;
                    case EVENT_CALL_OF_HIREEK:
                        DoCastSelf(SPELL_CALL_OF_HIREEK);
                        events.ScheduleEvent(EVENT_CALL_OF_HIREEK, 60s, 0, PHASE_TROLL);
                        break;
                    case EVENT_GREATER_HEAL:
                        Talk(EMOTE_GREAT_HEAL);
                        DoCastSelf(SPELL_GREATER_HEAL);
                        events.ScheduleEvent(EVENT_GREATER_HEAL, 46s, 0, PHASE_TROLL);
                        break;
                    case EVENT_BATTERING_CHARGE:
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, [this](Unit* u) { return u->IsPlayer() && !me->IsWithinMeleeRange(u); }))
                            DoCast(target, SPELL_BATTERING_CHARGE);
                        events.ScheduleEvent(EVENT_BATTERING_CHARGE, 20s, 0, PHASE_BAT);
                        break;
                    case EVENT_SCREECH:
                        DoCastSelf(SPELL_SCREECH);
                        events.ScheduleEvent(EVENT_SCREECH, 20s, 0, PHASE_BAT);
                        break;
                    case EVENT_BAT_RIDER:
                        if (_riders < 2)
                        {
                            Talk(SAY_CALL_RIDERS);
                            if (me->SummonCreature(NPC_BATRIDER, SpawnBatRider, TEMPSUMMON_TIMED_DESPAWN_OUT_OF_COMBAT))
                                ++_riders;
                            if (_riders < 2)
                                events.ScheduleEvent(EVENT_BAT_RIDER, 10s, 15s, 0, PHASE_BAT);
                        }
                        break;
                }

                if (me->HasUnitState(UNIT_STATE_CASTING))
                    break;
            }

            DoMeleeAttackIfReady();
        }

    private:
        bool _bat = false;
        uint8 _riders = 0;
        ObjectGuid _target;
    };
}

void AddCoaJeklikScripts()
{
    RegisterZulGurubCreatureAI(boss_jeklik_coa);
}

/*
 * High Priest Venoxis with Ascension's spells.
 *
 * Kit: Ascension's block 2118000-2118087. Timings: a Bronzebeard kill on video
 * (Ascension's mechanics, read off his cast bar at 10 frames a second), see
 * raid-difficulty-werkzeug/zg-video-zeitplan.json.
 *
 *   Troll form
 *     Holy Nova     first 7s,  every 18s   15 yards around him; heals him and
 *                                          his cobras for 6% of his health
 *     Renew         first 16s, every 24s   on himself, 2% of his health every 3s
 *     Holy Wrath    first 18s, every 15s   on the tank, arcs on
 *     Holy Fire     first 22s, every 10s   random player, hit and burn
 *
 *   Snake form, at 50% (the video: 47-50%)
 *     Toxic Bombardement  first 1s,  every 15s   toxic cloud at a random player
 *     Parasitic Poison    first 3s,  every 15s   random player; dispelled, a
 *                                                Parasitic Serpent breaks out
 *     Venom Spit          first 5s,  every 10s   everyone in front, stacks
 *                                                Virulent Poison
 *     Corpse Explosion    first 17s, every 40s   every snake corpse nearby
 *                                                bursts and leaves acid
 *     Poisonous Fangs     passive, his hits apply Virulent Poison
 *
 * Decided here, not in the data:
 *   - Holy Wrath jumps up to 4 times, 10 yards each, +50% per jump minus 2%
 *     per player above 10 (the tooltip's rule);
 *   - the transform is his own Aspect of Hethiss (2118023) instead of the
 *     stock snake spell;
 *   - Thrash and the frenzy at 20% stay from stock.
 */

#include "CreatureScript.h"
#include "ScriptedCreature.h"
#include "SpellAuraEffects.h"
#include "SpellScript.h"
#include "SpellScriptLoader.h"
#include "../../../src/server/scripts/EasternKingdoms/ZulGurub/zulgurub.h"
#include "zg_coa_common.h"

#include <list>

using namespace coa_zg;

namespace
{
    enum Says
    {
        SAY_TRANSFORM = 1,
        SAY_DEATH     = 2
    };

    enum Spells
    {
        SPELL_THRASH               = 3391,
        SPELL_FRENZY               = 8269,

        SPELL_RENEW                = 2118001,
        SPELL_HOLY_NOVA            = 2118002,
        SPELL_HOLY_NOVA_HIT        = 2118003,
        SPELL_HOLY_NOVA_HEAL       = 2118007,
        INFO_HOLY_FIRE             = 2118008,
        SPELL_HOLY_FIRE            = 2118012,
        SPELL_HOLY_FIRE_DOT        = 2118013,
        SPELL_HOLY_FIRE_HIT        = 2118014,
        INFO_HOLY_WRATH            = 2118016,
        SPELL_HOLY_WRATH           = 2118020,
        SPELL_HOLY_WRATH_HIT       = 2118021,
        SPELL_ASPECT_OF_HETHISS    = 2118023,
        SPELL_POISONOUS_FANGS      = 2118025,
        SPELL_VIRULENT_POISON      = 2118026,
        SPELL_VENOM_SPIT           = 2118030,
        SPELL_VENOM_SPIT_HIT       = 2118031,
        SPELL_TOXIC_BOMBARDEMENT   = 2118035,
        SPELL_PARASITIC_POISON     = 2118040,
        SPELL_PARASITIC_POISON_DOT = 2118041,
        SPELL_CORPSE_EXPLOSION     = 2118045,
        SPELL_ACID_BURST           = 2118078,
        SPELL_ACID_POOL            = 2118082,
    };

    enum Npcs
    {
        NPC_RAZZASHI_COBRA    = 11373,
        NPC_PARASITIC_SERPENT = 14884,
        NPC_WORLD_TRIGGER     = 12999
    };

    enum Events
    {
        EVENT_THRASH = 1,
        EVENT_HOLY_NOVA,
        EVENT_RENEW,
        EVENT_HOLY_WRATH,
        EVENT_HOLY_FIRE,
        EVENT_TOXIC_BOMBARDEMENT,
        EVENT_PARASITIC_POISON,
        EVENT_VENOM_SPIT,
        EVENT_CORPSE_EXPLOSION,
    };

    enum Phases
    {
        PHASE_TROLL = 1,
        PHASE_SNAKE = 2
    };

    constexpr float HOLY_NOVA_RANGE  = 15.0f;
    constexpr float WRATH_JUMP_RANGE = 10.0f;
    constexpr uint8 WRATH_JUMPS      = 4;
    constexpr float SPIT_RANGE       = 60.0f;
    constexpr float SPIT_ARC         = float(M_PI) / 2;
    constexpr float CORPSE_RANGE     = 80.0f;

    struct boss_venoxis_coa : public BossAI
    {
        boss_venoxis_coa(Creature* creature) : BossAI(creature, DATA_VENOXIS) { }

        void Reset() override
        {
            BossAI::Reset();
            me->RemoveAllAuras();
            _snake = false;
            _frenzied = false;
            _burst.clear();
        }

        void JustEngagedWith(Unit* who) override
        {
            BossAI::JustEngagedWith(who);

            events.SetPhase(PHASE_TROLL);
            events.ScheduleEvent(EVENT_THRASH, 8s);
            events.ScheduleEvent(EVENT_HOLY_NOVA, 7s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_RENEW, 16s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_HOLY_WRATH, 18s, 0, PHASE_TROLL);
            events.ScheduleEvent(EVENT_HOLY_FIRE, 22s, 0, PHASE_TROLL);
        }

        void JustDied(Unit* killer) override
        {
            BossAI::JustDied(killer);
            Talk(SAY_DEATH);
            me->RemoveAllAuras();
        }

        void DamageTaken(Unit* attacker, uint32& damage, DamageEffectType type, SpellSchoolMask school) override
        {
            BossAI::DamageTaken(attacker, damage, type, school);

            if (!_snake && me->HealthBelowPctDamaged(50, damage))
            {
                _snake = true;
                me->InterruptNonMeleeSpells(false);
                DoCastSelf(SPELL_ASPECT_OF_HETHISS, true);
                DoCastSelf(SPELL_POISONOUS_FANGS, true);
                Talk(SAY_TRANSFORM);
                DoResetThreatList();

                events.SetPhase(PHASE_SNAKE);
                events.ScheduleEvent(EVENT_TOXIC_BOMBARDEMENT, 1s, 0, PHASE_SNAKE);
                events.ScheduleEvent(EVENT_PARASITIC_POISON, 3s, 0, PHASE_SNAKE);
                events.ScheduleEvent(EVENT_VENOM_SPIT, 5s, 0, PHASE_SNAKE);
                events.ScheduleEvent(EVENT_CORPSE_EXPLOSION, 17s, 0, PHASE_SNAKE);
            }

            if (!_frenzied && me->HealthBelowPctDamaged(20, damage))
            {
                _frenzied = true;
                DoCastSelf(SPELL_FRENZY, true);
            }
        }

        // The casts are dummies; what they do happens when they finish.
        void OnSpellCast(SpellInfo const* spell) override
        {
            BossAI::OnSpellCast(spell);

            switch (spell->Id)
            {
                case SPELL_HOLY_NOVA:
                    HolyNova();
                    break;
                case SPELL_HOLY_WRATH:
                    HolyWrath();
                    break;
                case SPELL_HOLY_FIRE:
                    if (Unit* target = ObjectAccessor::GetUnit(*me, _target))
                    {
                        Hit(me, target, SPELL_HOLY_FIRE_HIT, Info(me, INFO_HOLY_FIRE, 0));
                        Hit(me, target, SPELL_HOLY_FIRE_DOT, Info(me, INFO_HOLY_FIRE, 1));
                    }
                    break;
                case SPELL_VENOM_SPIT:
                    for (Player* p : PlayersInFront(me, SPIT_RANGE, SPIT_ARC))
                    {
                        me->CastSpell(p, SPELL_VENOM_SPIT_HIT, true);
                        AddStack(me, p, SPELL_VIRULENT_POISON);
                    }
                    break;
                case SPELL_PARASITIC_POISON:
                    if (Unit* target = ObjectAccessor::GetUnit(*me, _target))
                        me->CastSpell(target, SPELL_PARASITIC_POISON_DOT, true);
                    break;
                case SPELL_CORPSE_EXPLOSION:
                    CorpseExplosion();
                    break;
                default:
                    break;
            }
        }

        void HolyNova()
        {
            for (Player* p : PlayersWithin(me, HOLY_NOVA_RANGE))
                me->CastSpell(p, SPELL_HOLY_NOVA_HIT, true);

            int32 heal = int32(me->CountPctFromMaxHealth(6));
            std::list<Creature*> allies;
            me->GetCreatureListWithEntryInGrid(allies, NPC_RAZZASHI_COBRA, HOLY_NOVA_RANGE);
            allies.push_back(me);
            for (Creature* ally : allies)
                if (ally->IsAlive())
                    me->CastCustomSpell(ally, SPELL_HOLY_NOVA_HEAL, &heal, nullptr, nullptr, true);
        }

        void HolyWrath()
        {
            Unit* first = ObjectAccessor::GetUnit(*me, _target);
            Player* current = first ? first->ToPlayer() : nullptr;
            if (!current)
                return;

            int32 const players = int32(Players(me, [](Player*) { return true; }).size());
            float const step = 1.0f + std::max(0, (Info(me, INFO_HOLY_WRATH, 1) - 1) - 2 * std::max(0, players - 10)) / 100.0f;
            float amount = float(Info(me, INFO_HOLY_WRATH, 0));

            std::vector<Player*> hit;
            for (uint8 i = 0; current && i <= WRATH_JUMPS; ++i)
            {
                Hit(me, current, SPELL_HOLY_WRATH_HIT, int32(amount));
                hit.push_back(current);
                amount *= step;
                current = NextInChain(me, current, WRATH_JUMP_RANGE, hit);
            }
        }

        // Every snake corpse nearby bursts once and leaves a pool of acid.
        void CorpseExplosion()
        {
            std::list<Creature*> corpses;
            me->GetCreatureListWithEntryInGrid(corpses, NPC_RAZZASHI_COBRA, CORPSE_RANGE);
            std::list<Creature*> serpents;
            me->GetCreatureListWithEntryInGrid(serpents, NPC_PARASITIC_SERPENT, CORPSE_RANGE);
            corpses.splice(corpses.end(), serpents);

            for (Creature* corpse : corpses)
            {
                if (corpse->IsAlive() || _burst.count(corpse->GetGUID()))
                    continue;
                _burst.insert(corpse->GetGUID());

                if (Creature* spot = me->SummonCreature(NPC_WORLD_TRIGGER, corpse->GetPosition(), TEMPSUMMON_MANUAL_DESPAWN))
                {
                    spot->SetFaction(me->GetFaction());
                    spot->CastSpell(spot, SPELL_ACID_BURST, true, nullptr, nullptr, me->GetGUID());
                    spot->CastSpell(spot, SPELL_ACID_POOL, true, nullptr, nullptr, me->GetGUID());
                }
                corpse->DespawnOrUnsummon(1s);
            }
        }

        void CastOnRandom(uint32 spell)
        {
            if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, 100.0f, true))
            {
                _target = target->GetGUID();
                DoCast(target, spell);
            }
        }

        void UpdateAI(uint32 diff) override
        {
            if (!UpdateVictim())
                return;

            events.Update(diff);

            if (me->HasUnitState(UNIT_STATE_CASTING))
                return;

            while (uint32 eventId = events.ExecuteEvent())
            {
                switch (eventId)
                {
                    case EVENT_THRASH:
                        DoCastSelf(SPELL_THRASH, true);
                        events.ScheduleEvent(EVENT_THRASH, 10s, 20s);
                        break;
                    case EVENT_HOLY_NOVA:
                        DoCastSelf(SPELL_HOLY_NOVA);
                        events.ScheduleEvent(EVENT_HOLY_NOVA, 18s, 0, PHASE_TROLL);
                        break;
                    case EVENT_RENEW:
                    {
                        int32 heal = int32(me->CountPctFromMaxHealth(2));
                        me->CastCustomSpell(me, SPELL_RENEW, &heal, nullptr, nullptr, false);
                        events.ScheduleEvent(EVENT_RENEW, 24s, 0, PHASE_TROLL);
                        break;
                    }
                    case EVENT_HOLY_WRATH:
                        if (Unit* tank = me->GetVictim())
                        {
                            _target = tank->GetGUID();
                            DoCast(tank, SPELL_HOLY_WRATH);
                        }
                        events.ScheduleEvent(EVENT_HOLY_WRATH, 15s, 0, PHASE_TROLL);
                        break;
                    case EVENT_HOLY_FIRE:
                        CastOnRandom(SPELL_HOLY_FIRE);
                        events.ScheduleEvent(EVENT_HOLY_FIRE, 10s, 0, PHASE_TROLL);
                        break;
                    case EVENT_TOXIC_BOMBARDEMENT:
                        if (Unit* target = SelectTarget(SelectTargetMethod::Random, 0, 100.0f, true))
                            me->CastSpell(target->GetPositionX(), target->GetPositionY(), target->GetPositionZ(), SPELL_TOXIC_BOMBARDEMENT, false);
                        events.ScheduleEvent(EVENT_TOXIC_BOMBARDEMENT, 15s, 0, PHASE_SNAKE);
                        break;
                    case EVENT_PARASITIC_POISON:
                        CastOnRandom(SPELL_PARASITIC_POISON);
                        events.ScheduleEvent(EVENT_PARASITIC_POISON, 15s, 0, PHASE_SNAKE);
                        break;
                    case EVENT_VENOM_SPIT:
                        DoCastVictim(SPELL_VENOM_SPIT);
                        events.ScheduleEvent(EVENT_VENOM_SPIT, 10s, 0, PHASE_SNAKE);
                        break;
                    case EVENT_CORPSE_EXPLOSION:
                        DoCastSelf(SPELL_CORPSE_EXPLOSION);
                        events.ScheduleEvent(EVENT_CORPSE_EXPLOSION, 40s, 0, PHASE_SNAKE);
                        break;
                }

                if (me->HasUnitState(UNIT_STATE_CASTING))
                    break;
            }

            DoMeleeAttackIfReady();
        }

    private:
        bool _snake = false;
        bool _frenzied = false;
        ObjectGuid _target;
        GuidSet _burst;
    };

